math.push(...[["Triângulos","Um triângulo com exatamente dois lados iguais é:",["Escaleno","Isósceles","Equilátero","Obtusângulo"],1,"Isósceles tem dois lados de mesma medida."],["Triângulos","Qual conjunto NÃO pode formar um triângulo?",["3, 4 e 5","5, 5 e 8","2, 3 e 6","6, 7 e 8"],2,"Para formar triângulo, a soma de dois lados deve ser maior que o terceiro. 2 + 3 = 5, menor que 6."],["Triângulos","Um triângulo retângulo possui um ângulo de:",["45°","60°","90°","120°"],2,"Por definição, possui um ângulo reto de 90°."],["Triângulos","Um triângulo tem lados 5, 5 e 6. Quanto ao comprimento dos lados, ele é:",["Escaleno","Isósceles","Equilátero","Retângulo"],1,"Há dois lados iguais, portanto é isósceles."],["Triângulos","A soma dos ângulos internos de qualquer triângulo é:",["90°","180°","270°","360°"],1,"A soma interna de um triângulo é sempre 180°."],["Triângulos","Um triângulo tem ângulos 90° e 35°. O terceiro ângulo mede:",["45°","50°","55°","65°"],2,"180° − 90° − 35° = 55°."],["Teorema de Pitágoras","Um triângulo retângulo tem catetos de 5 cm e 12 cm. Qual é a hipotenusa?",["13 cm","15 cm","17 cm","19 cm"],0,"5² + 12² = 25 + 144 = 169; √169 = 13."],["Teorema de Pitágoras","Uma escada de 13 m encosta numa parede e sua base está a 5 m da parede. Qual altura alcança?",["8 m","10 m","12 m","14 m"],2,"h² + 5² = 13²; h² = 144; h = 12."],["Teorema de Pitágoras","Um retângulo mede 8 m por 15 m. Qual é sua diagonal?",["16 m","17 m","18 m","19 m"],1,"8² + 15² = 64 + 225 = 289; √289 = 17."],["Teorema de Pitágoras","Um triângulo retângulo tem hipotenusa 10 e um cateto 6. Quanto mede o outro cateto?",["4","6","8","12"],2,"x² + 6² = 10²; x² = 64; x = 8."],["Teorema de Pitágoras","Qual trio forma um triângulo retângulo?",["6, 8, 10","6, 7, 9","5, 6, 8","4, 5, 7"],0,"6² + 8² = 36 + 64 = 100 = 10²."],["Teorema de Pitágoras","Uma tela retangular mede 9 cm por 40 cm. Qual é sua diagonal?",["39 cm","40 cm","41 cm","49 cm"],2,"9² + 40² = 81 + 1600 = 1681; √1681 = 41."],["Teorema de Pitágoras","Um triângulo retângulo tem catetos 7 e 24. Qual a hipotenusa?",["23","24","25","26"],2,"7² + 24² = 49 + 576 = 625; √625 = 25."],["Teorema de Pitágoras","Uma rampa tem 15 m de comprimento e vence 9 m de altura. Qual a distância horizontal?",["10 m","12 m","13 m","14 m"],1,"x² + 9² = 15²; x² = 144; x = 12."],["Média aritmética","As notas 5, 7, 8 e 10 têm média igual a:",["7","7,5","8","8,5"],1,"(5+7+8+10)=30; 30÷4=7,5."],["Média aritmética","Os tempos 12, 14 e 16 minutos têm média de:",["13","14","15","16"],1,"(12+14+16)=42; 42÷3=14."],["Média aritmética","A média de 6 e 10 é:",["7","8","9","10"],1,"(6+10)÷2=8."],["Média aritmética","Quatro caixas pesam 18, 20, 22 e 24 kg. Qual o peso médio?",["20 kg","21 kg","22 kg","23 kg"],1,"84÷4=21 kg."],["Média aritmética","Uma pessoa caminhou 3, 5, 4, 6 e 7 km em cinco dias. Qual a média diária?",["4 km","5 km","6 km","7 km"],1,"3+5+4+6+7=25; 25÷5=5 km."],["Média aritmética","As temperaturas foram 28°C, 30°C e 32°C. Qual a média?",["29°C","30°C","31°C","32°C"],1,"(28+30+32)=90; 90÷3=30°C."],["Média aritmética","A média de três números é 20. Se dois deles são 18 e 22, qual é o terceiro?",["18","20","22","24"],1,"Soma total = 3×20 = 60. Terceiro = 60−18−22 = 20."],["Média aritmética","A média de quatro provas é 7. A soma das notas é:",["21","24","28","32"],2,"Soma = média × quantidade = 7 × 4 = 28."],["Números e operações","Uma caixa contém 144 lápis distribuídos igualmente em 12 pacotes. Quantos lápis há por pacote?",["10","12","14","16"],1,"144 ÷ 12 = 12."],["Números e operações","Uma escola comprou 18 caixas com 24 cadernos cada. Quantos cadernos foram comprados?",["382","412","432","452"],2,"18 × 24 = 432."],["Números e operações","Um ônibus saiu com 52 passageiros. Desceram 19 e subiram 7. Quantos ficaram?",["36","38","40","42"],2,"52 − 19 + 7 = 40."],["Números e operações","Qual é o valor de 3 × (12 + 8)?",["36","48","60","72"],2,"Primeiro resolva o parêntese: 12+8=20. Depois 3×20=60."],["Números e operações","Qual é o resultado de 120 ÷ 6 + 15?",["30","35","40","45"],1,"120÷6=20; 20+15=35."],["Números e operações","Um ingresso custa R$ 27. Quanto custam 4 ingressos?",["R$ 98","R$ 104","R$ 108","R$ 112"],2,"27 × 4 = 108."],["Números e operações","Uma caixa d'água recebeu 350 L pela manhã e 275 L à tarde. Se já tinha 125 L, com quantos litros ficou?",["625 L","700 L","750 L","800 L"],2,"125 + 350 + 275 = 750 L."],["Números e operações","Um estoque tinha 1.000 unidades e vendeu 375. Quantas restaram?",["575","600","625","675"],2,"1.000 − 375 = 625."]]);
port.push(...[["Metáfora","“O tempo é um ladrão.” Essa metáfora sugere que o tempo:",["Comete crimes literalmente","Leva momentos e oportunidades","Usa máscara","Entra em casas"],1,"A figura atribui ao tempo a ideia de retirar algo de nós."],["Comparação","Qual frase apresenta comparação explícita?",["O menino é um foguete","O menino corre como um foguete","O menino correu ontem","O foguete subiu"],1,"A palavra “como” estabelece comparação direta."],["Comparação","Em “A água estava fria como gelo”, há comparação entre:",["Água e gelo","Água e fogo","Frio e calor","Gelo e sol"],0,"A água é comparada explicitamente ao gelo."],["Comparação","Qual frase contém comparação?",["Seus olhos eram estrelas","Seus olhos brilhavam como estrelas","As estrelas surgiram","Ela fechou os olhos"],1,"“Como” marca a comparação explícita."],["Comparação","“Ele ficou pálido feito papel.” O termo “feito” introduz:",["Uma comparação","Uma ordem","Uma conclusão","Uma pergunta"],0,"“Feito” tem valor comparativo, aproximando a palidez da cor do papel."],["Comparação","Em qual alternativa há comparação?",["A cidade dormia","A cidade era um gigante","A cidade parecia um labirinto","A cidade cresceu"],2,"“Parecia” estabelece relação comparativa."],["Comparação","“A voz dela soava como música.” O efeito de sentido é:",["Comparar a voz à música","Dizer que ela tocava instrumento","Informar o volume exato","Negar que ela falava"],0,"A voz é aproximada da música por semelhança."],["Comparação","Qual frase usa uma comparação explícita?",["Ele é uma rocha","Ele é firme como uma rocha","A rocha é firme","Ele segurou a rocha"],1,"A construção “como uma rocha” torna a comparação explícita."],["Ironia","Depois de alguém derrubar todos os papéis no chão, outra pessoa diz: “Que organização perfeita!”. O efeito é de:",["Ironia","Elogio literal","Comparação","Descrição neutra"],0,"A fala afirma o contrário do que a situação evidencia."],["Ironia","Ao enfrentar uma fila enorme, alguém comenta: “Que rapidez impressionante!”. Isso é:",["Ironia","Metáfora","Informação objetiva","Ordem"],0,"A expressão positiva contrasta com a demora real."],["Ironia","Em um dia de chuva forte, dizer “Que ótimo tempo para um piquenique!” pode produzir:",["Ironia","Definição","Notícia","Comparação literal"],0,"A fala contrasta com a situação desfavorável."],["Ironia","Após tirar nota muito baixa, um aluno diz “Fui brilhante nessa prova”. O efeito pode ser:",["Ironia","Personificação","Hipérbole necessariamente","Informação factual"],0,"O elogio a si mesmo contrasta com o resultado baixo."],["Ironia","Ao entrar num quarto bagunçado e dizer “Nossa, tudo no lugar!”, ocorre:",["Ironia","Metáfora","Comparação","Narrativa"],0,"A fala significa o contrário da situação observada."],["Ironia","Quando o computador trava pela quinta vez e alguém diz “Tecnologia maravilhosa!”, há:",["Ironia","Elogio literal obrigatório","Descrição técnica","Regra"],0,"O contexto negativo transforma a frase em crítica irônica."],["Ironia","Depois de perder o ônibus por segundos, alguém diz “Meu timing é excelente”. O efeito é:",["Ironia","Comparação","Personificação","Informação objetiva"],0,"A situação contradiz a avaliação positiva."],["Hipérbole","“Estou morrendo de fome.” A expressão é um exemplo de:",["Hipérbole","Comparação","Metáfora literal","Informação exata"],0,"Há exagero intencional para intensificar a fome."],["Hipérbole","“Já te esperei mil anos.” O efeito de sentido é de:",["Exagero","Precisão histórica","Comparação","Personificação"],0,"O tempo é exagerado para enfatizar a longa espera."],["Hipérbole","“Chorei um oceano inteiro.” A figura predominante é:",["Hipérbole","Ironia","Comparação","Eufemismo"],0,"“Um oceano” exagera a quantidade de lágrimas."],["Hipérbole","“Tenho uma montanha de tarefas.” A expressão indica:",["Grande quantidade de tarefas","Uma montanha literal","Poucas tarefas","Uma tarefa de geografia apenas"],0,"“Montanha” exagera a quantidade."],["Hipérbole","“Ele correu mais rápido que o vento e chegou em um segundo.” O trecho usa exagero para indicar:",["Grande velocidade","Imobilidade","Sono","Silêncio"],0,"O exagero intensifica a ideia de rapidez."],["Hipérbole","“A mochila pesa uma tonelada.” A frase quer dizer que:",["A mochila parece muito pesada","A mochila pesa exatamente 1.000 kg","A mochila está vazia","A mochila é de metal"],0,"“Uma tonelada” é exagero para enfatizar peso."],["Hipérbole","“Ri até a barriga doer por cem horas.” O recurso expressivo é:",["Hipérbole","Ironia","Definição","Notícia"],0,"“Cem horas” exagera a duração da risada."],["Personificação","Em “O vento cantava entre as árvores”, ocorre:",["Personificação","Comparação","Ironia","Fato científico"],0,"O vento recebe a ação humana de cantar."],["Personificação","“A lua observava a cidade.” A frase apresenta:",["Personificação","Hipérbole","Comparação explícita","Notícia"],0,"A lua recebe a ação humana de observar."],["Personificação","Qual frase contém personificação?",["A chuva caiu forte","A chuva bateu à porta pedindo entrada","A porta estava molhada","O dia estava frio"],1,"A chuva é apresentada como se pudesse pedir entrada."],["Personificação","Em “O relógio corre quando estou atrasado”, há personificação porque:",["O relógio recebe uma ação própria de ser vivo","O relógio marca horas","Há uma comparação com números","O relógio está quebrado"],0,"“Correr” é atribuído figuradamente ao relógio."],["Personificação","“As folhas dançavam com o vento.” O recurso é:",["Personificação","Fato objetivo apenas","Ironia","Argumentação"],0,"Folhas recebem a ação humana de dançar."],["Personificação","Qual alternativa apresenta personificação?",["O sol aquece a Terra","O sol sorriu pela janela","O sol nasceu às 6h","O sol é uma estrela"],1,"“Sorrir” é uma ação humana atribuída ao sol."],["Personificação","Em “A cidade nunca dorme”, a cidade é apresentada como se pudesse:",["Dormir","Voar","Ler","Nadar"],0,"Atribui-se à cidade uma ação humana: dormir."],["Ideia principal","“Organizar o tempo de estudo em blocos curtos, com pequenas pausas, pode ajudar a manter a concentração.” A principal mensagem é:",["Estudar sem parar é melhor","Pausas sempre atrapalham","Blocos curtos com pausas podem favorecer a concentração","Só é possível estudar por poucos minutos"],2,"O texto recomenda uma organização do estudo que favoreça a concentração."]]);

function drawPracticeVaried(pool,count,key){
  state.seen=state.seen||{};
  let seen=new Set(state.seen[key]||[]);
  const weak=state.errors.reduce((a,e)=>(a[e.topic]=(a[e.topic]||0)+1,a),{});
  let available=pool.filter(q=>!seen.has(q[1]));
  if(available.length<count){seen=new Set();available=[...pool]}
  available=shuffle(available).sort((a,b)=>(weak[b[0]]||0)-(weak[a[0]]||0));
  const picked=available.slice(0,count);
  state.seen[key]=[...seen,...picked.map(q=>q[1])];
  save();
  return picked;
}
practice=function(sub='priority'){
  const pool=sub==='port'?port:sub==='math'?math:[...math,...port];
  const key=sub==='port'?'practice-port':sub==='math'?'practice-math':'practice-priority';
  practiceSet=drawPracticeVaried(pool,5,key);
  practiceIndex=0;
  renderPractice();
};
routes.practice=practice;
